cypher.cypher:
MATCH (d:DataProduct) WHERE toLower(d.name) CONTAINS toLower($t)
                   OR EXISTS { (d)-[:REALIZES]->(c:Concept) WHERE toLower(c.name) = toLower($t) }
                RETURN d.id AS id

